def consecutiveSumWays(n):
    while n % 2 == 0:
        n //= 2
    ways = 1
    p = 3
    while p * p <= n:
        if n % p == 0:
            e = 0
            while n % p == 0:
                n //= p
                e += 1
            ways *= e + 1
        p += 2
    if n > 1:
        ways *= 2
    return ways
